// L5-D38: Material and Cupertino icons are replaced by Lucide through
// ExomIcons. This sweep fails when lib/ still references `Icons.` or
// `CupertinoIcons.` outside the justified exceptions.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

/// Justified exceptions: file path (relative to the repository root, with
/// forward slashes) -> reason. Empty on purpose; add an entry only for an icon
/// generated by a framework widget that cannot be replaced without changing
/// behaviour.
const Map<String, String> _exceptions = <String, String>{};

void main() {
  test('lib/ has no Material/Cupertino icon references', () {
    final RegExp pattern = RegExp(r'(?<![A-Za-z0-9_])(Cupertino)?Icons\.\w');
    final List<String> offenders = <String>[];
    for (final FileSystemEntity entity in Directory(
      'lib',
    ).listSync(recursive: true)) {
      if (entity is! File || !entity.path.endsWith('.dart')) continue;
      final String path = entity.path.replaceAll(r'\', '/');
      if (_exceptions.containsKey(path)) continue;
      final List<String> lines = entity.readAsLinesSync();
      for (int i = 0; i < lines.length; i++) {
        if (pattern.hasMatch(lines[i])) offenders.add('$path:${i + 1}');
      }
    }
    expect(offenders, isEmpty, reason: offenders.join('\n'));
  });

  test('every exception still exists and carries a reason', () {
    _exceptions.forEach((String path, String reason) {
      expect(File(path).existsSync(), isTrue, reason: path);
      expect(reason.trim(), isNotEmpty, reason: path);
    });
  });
}
